// PostgreSQL store for Guiyan — adapted from the original group demo
// (guiyan-demo/server/postgres.mjs): pg pool, int8/numeric parsed as Number,
// advisory lock for first-boot seeding, schema conversion
// INTEGER PRIMARY KEY -> GENERATED BY DEFAULT AS IDENTITY, batch seeding.
// Changes: no Vercel dependency (plain Node + pg only); demo seed passwords
// come from DEMO_PASSWORD / ADMIN_PASSWORD environment variables.

import { AsyncLocalStorage } from "node:async_hooks";
import pg from "pg";
import { schema } from "./schema.mjs";
import { seedStatements } from "./seed.mjs";
import { enrichCatalog } from "./catalog-content.mjs";
import { defaultTagRules } from "./lib/profiles.mjs";
import { DEFAULT_TIERS } from "./routes/member-tiers.mjs";
import { DEFAULT_MEMBER_INSIGHT_RULES } from "./routes/member-insights.mjs";
import { DEFAULT_PLANS } from "./routes/stored-value.mjs";
import { issueTicketsForOrder } from "./routes/tickets.mjs";

// PostgreSQL aggregates return int8/numeric strings; the demo API uses numbers.
pg.types.setTypeParser(20, Number);
pg.types.setTypeParser(1700, Number);
const writeLock = 71426011;

export function postgresSql(sql) {
  let index = 0;
  return sql.replace(/'(?:''|[^'])*'|\?/g, (token) =>
    token === "?" ? `$${++index}` : token,
  );
}

export async function openPostgresStore(
  connectionString,
  { poolOptions = {} } = {},
) {
  if (!connectionString) throw new Error("DATABASE_URL is required");
  const connection = new URL(connectionString);
  if (connection.searchParams.get("sslmode") === "require")
    connection.searchParams.set("sslmode", "verify-full");
  const pool = new pg.Pool({
    connectionString: connection.toString(),
    max: 3,
    idleTimeoutMillis: 5000,
    connectionTimeoutMillis: 15000,
    ...poolOptions,
  });
  pool.on("error", (error) =>
    console.error("Database pool error", { code: error.code }),
  );
  const context = new AsyncLocalStorage();
  const execute = (sql, params = []) =>
    (context.getStore() || pool).query(postgresSql(sql), params);

  try {
    const client = await pool.connect();
    try {
      await client.query("BEGIN");
      await client.query("SELECT pg_advisory_xact_lock($1)", [writeLock]);
      await client.query(
        schema.replaceAll(
          "id INTEGER PRIMARY KEY",
          "id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
        ),
      );
      await client.query(
        "ALTER TABLE comments ADD COLUMN IF NOT EXISTS dimensions TEXT NOT NULL DEFAULT '{}'",
      );
      // Wave 4 #13: admin decision on a refund/dispute (approval text or
      // the admin's rejection reason). Same idempotent pattern as above;
      // the user's own reason stays in orders.refund_reason.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS refund_decision TEXT DEFAULT ''",
      );
      // Phase 3 (registration): optional email on users. Fresh databases
      // get it from schema.mjs; existing ones (incl. live Neon) get it
      // here, same precedent as the dimensions column above.
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS email TEXT",
      );
      // Account tabs (2026-11-12): avatar storage key (null = initial
      // letter). Same idempotent pattern as email above.
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar TEXT",
      );
      // Account tabs (2026-11-12): social links as one JSON object
      // (keys: douyin/wechat/xiaohongshu; '{}' = none linked).
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS social_links TEXT DEFAULT '{}'",
      );
      // OTP for contact changes (2026-11-12, Lam): phone number, new
      // column for the PATCH /api/account/phone endpoint. Same idempotent
      // pattern as the columns above; verification_codes is a new table
      // and comes from schema.mjs (CREATE TABLE IF NOT EXISTS runs on
      // every setup, fresh and existing DBs alike); its `verified_at`
      // column is part of the same CREATE TABLE (the table never existed
      // on any live DB before this change, so no ALTER is needed).
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS phone TEXT",
      );
      // R1-1 (multi-shop, 2026-11-13): shop scoping on users + resources.
      // Same idempotent pattern as the columns above.
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS shop_id INTEGER REFERENCES shops(id)",
      );
      await client.query(
        "ALTER TABLE resources ADD COLUMN IF NOT EXISTS shop_id INTEGER REFERENCES shops(id)",
      );
      // R1-2 (admin accounts, 2026-11-13): account status for
      // enable/disable. DEFAULT 'active' fills existing rows.
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'active'",
      );
      // R1-3 (shop theming, 2026-11-13): per-shop storefront theme as
      // JSON text (banner, primaryColor, sections); NULL = default theme.
      await client.query(
        "ALTER TABLE shops ADD COLUMN IF NOT EXISTS theme TEXT",
      );
      // R2-2 (price tiers, 2026-11-13): tier orders link the performance +
      // ticket type; NULL = the old resource-price flow. Same idempotent
      // pattern as the columns above.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS performance_id INTEGER REFERENCES performances(id)",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS ticket_type_id INTEGER REFERENCES ticket_types(id)",
      );
      // R2-3 (pickup points + ticket templates, 2026-11-13): the
      // pickup point a tier order chose; NULL = the old flow or a
      // show with no pickup points. Same idempotent pattern.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS pickup_point_id INTEGER REFERENCES pickup_points(id)",
      );
      // R2-4 (venues, 2026-11-13): the venue a resource is staged in;
      // NULL = the old flow (no venue link). Same idempotent pattern.
      // The venues table itself comes from schema.mjs above, so the
      // FK target exists before this ALTER runs.
      await client.query(
        "ALTER TABLE resources ADD COLUMN IF NOT EXISTS venue_id INTEGER REFERENCES venues(id)",
      );
      // R3-1 (member tiers, 2026-11-13): the tier a user holds (main
      // shop only — see routes/member-tiers.mjs) and the discount a
      // single order actually got (snapshot of the tier at order time).
      // Same idempotent pattern as the columns above.
      await client.query(
        "ALTER TABLE users ADD COLUMN IF NOT EXISTS tier_id INTEGER REFERENCES member_tiers(id)",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS discount_cents INTEGER NOT NULL DEFAULT 0",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS tier_id INTEGER REFERENCES member_tiers(id)",
      );
      // R3-2 (coupons, 2026-11-13): the coupon an order used (snapshot)
      // and how much it actually took off. The coupons +
      // coupon_redemptions tables themselves come from schema.mjs
      // above, so the FK targets exist before these ALTERs run.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS coupon_id INTEGER REFERENCES coupons(id)",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS coupon_cents INTEGER NOT NULL DEFAULT 0",
      );
      // R3-3 (flash sales, 2026-11-14): the flash sale an order used
      // (snapshot) and how much it actually took off. The flash_sales
      // table itself comes from schema.mjs above, so the FK target
      // exists before these ALTERs run.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS flash_sale_id INTEGER REFERENCES flash_sales(id)",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS flash_cents INTEGER NOT NULL DEFAULT 0",
      );
      // R3-6 (stored value, 2026-11-14): what one order actually took
      // from the card (snapshot at pay time). The
      // stored_value_accounts / stored_value_ledger /
      // stored_value_plans tables themselves come from schema.mjs
      // above, so the FK targets exist before this ALTER runs.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS stored_value_cents INTEGER NOT NULL DEFAULT 0",
      );
      // R4-4 (partial refund, 2026-11-14): cumulative refunded
      // tickets / money, plus the ticket ids of the current manual
      // partial-refund request ([] = none / a full-refund request).
      // Adding these columns ACTIVATES the R4-1/R4-2/R4-3 freeze
      // checks (tickets.mjs probes information_schema for
      // pending_refund_tickets): a ticket in a pending request now
      // refuses verify/print/batch with 400.
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS refund_quantity INTEGER NOT NULL DEFAULT 0",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS refunded_cents INTEGER NOT NULL DEFAULT 0",
      );
      await client.query(
        "ALTER TABLE orders ADD COLUMN IF NOT EXISTS pending_refund_tickets TEXT DEFAULT '[]'",
      );
      // R5-1 (events + batch aggregation, 2026-11-14): how long a
      // dwell event lasted, in ms. Fresh databases get it from
      // schema.mjs; existing ones get it here, same idempotent
      // pattern as the columns above. view/click/search write 0.
      await client.query(
        "ALTER TABLE events ADD COLUMN IF NOT EXISTS duration_ms INTEGER NOT NULL DEFAULT 0",
      );
      if (!(await client.query("SELECT COUNT(*) AS n FROM users")).rows[0].n) {
        // Batch adjacent inserts to keep first-time setup fast over the network.
        const groups = [];
        for (const [sql, params] of seedStatements({
          demo: process.env.DEMO_PASSWORD,
          admin: process.env.ADMIN_PASSWORD,
        })) {
          const last = groups.at(-1);
          if (last?.sql === sql) last.rows.push(params);
          else groups.push({ sql, rows: [params] });
        }
        for (const { sql, rows } of groups) {
          const [, prefix, values] = sql.match(
            /^(.*\bVALUES)\(([^()]*)\)\s*$/i,
          );
          const batch = `${prefix} ${rows.map(() => `(${values})`).join(",")}`;
          await client.query(postgresSql(batch), rows.flat());
        }
      }
      await enrichCatalog({
        prepare(sql) {
          const query = (...params) => client.query(postgresSql(sql), params);
          return {
            all: async (...params) => (await query(...params)).rows,
            get: async (...params) => (await query(...params)).rows[0],
            run: query,
          };
        },
      });
      // R1-1 main-shop backfill. It MUST run after the user seed and
      // after enrichCatalog above: the shop's owner is the platform
      // admin (id 1, FK shops.owner_id -> users) and every seeded
      // resource (demo + catalog) belongs to it. Created once, never
      // duplicated (WHERE NOT EXISTS guard, same pattern as the
      // tagRules backfill below); existing users keep shop_id NULL
      // (= platform level, all shops). Runs on every setup; only rows
      // still NULL are touched.
      await client.query(
        "INSERT INTO shops(id,parent_id,name,owner_id,status,created_at) SELECT 1,NULL,'桂演平台总店',1,'active',$1 WHERE NOT EXISTS (SELECT 1 FROM shops)",
        [new Date().toISOString()],
      );
      // The explicit id=1 above does NOT advance the identity
      // sequence, so the next auto-generated shop id would collide
      // with the main shop (23505 on create). Point the sequence past
      // the highest shop id; idempotent on every setup.
      await client.query(
        "SELECT setval(pg_get_serial_sequence('shops','id'), (SELECT MAX(id) FROM shops))",
      );
      await client.query(
        "UPDATE resources SET shop_id=1 WHERE shop_id IS NULL",
      );
      // R3-1 default member tiers (2026-11-13): the main shop's four
      // tiers, inserted once when shop 1 has none (guard pattern, same
      // as the main-shop backfill above). An admin's later edits are
      // never overwritten — only an empty tier list is seeded. The
      // tier rows themselves live in routes/member-tiers.mjs
      // (DEFAULT_TIERS); this block only runs the seed insert.
      {
        const existing = await client.query(
          "SELECT COUNT(*) AS n FROM member_tiers WHERE shop_id=1",
        );
        if (Number(existing.rows[0].n) === 0) {
          for (const t of DEFAULT_TIERS)
            await client.query(
              "INSERT INTO member_tiers(shop_id,name,min_spend_cents,discount_pct,benefits,created_at) VALUES(1,$1,$2,$3,$4,$5)",
              [
                t.name,
                t.min_spend_cents,
                t.discount_pct,
                t.benefits,
                new Date().toISOString(),
              ],
            );
        }
      }
      // R3-6 default stored-value plans (2026-11-14): the main shop's
      // three top-up plans, inserted once when shop 1 has none (guard
      // pattern, same as the tier backfill above). An admin's later
      // edits are never overwritten — only an empty plan list is
      // seeded. The plan rows themselves live in
      // routes/stored-value.mjs (DEFAULT_PLANS); this block only runs
      // the seed insert.
      {
        const existing = await client.query(
          "SELECT COUNT(*) AS n FROM stored_value_plans WHERE shop_id=1",
        );
        if (Number(existing.rows[0].n) === 0) {
          for (const t of DEFAULT_PLANS)
            await client.query(
              "INSERT INTO stored_value_plans(shop_id,amount_cents,bonus_cents,status,created_at) VALUES(1,$1,$2,'active',$3)",
              [
                t.amount_cents,
                t.bonus_cents,
                new Date().toISOString(),
              ],
            );
        }
      }
      // R2-4 venue backfill (2026-11-13, Lam option (a): rule as
      // written, count corrected 3 -> 6). Venue-category resources
      // whose meta carries seatRows/seatCols and whose venue_id is
      // still NULL get a venue (name = resource name, capacity =
      // seatRows x seatCols, address = meta.address); a same-name
      // venue in the resource's shop is reused, never duplicated.
      // Runs on every setup; only venue_id NULL rows are touched.
      // Fresh DB: 2 demo venues (广西文化艺术中心 20x20, 南宁小剧场
      // 11x20) + 4 catalog venues (10x18) = 6 venues. meta.seatRows /
      // seatCols stay untouched (fallback for the old display-only
      // seat map until R2-5).
      {
        const venueRows = await client.query(
          "SELECT id, shop_id, name, meta FROM resources WHERE category='venue' AND venue_id IS NULL",
        );
        for (const r of venueRows.rows) {
          let meta = {};
          try {
            meta = JSON.parse(r.meta || "{}") || {};
          } catch {
            meta = {};
          }
          const seatRows = Number(meta.seatRows);
          const seatCols = Number(meta.seatCols);
          if (
            !Number.isSafeInteger(seatRows) ||
            seatRows <= 0 ||
            !Number.isSafeInteger(seatCols) ||
            seatCols <= 0
          )
            continue;
          const existing = await client.query(
            "SELECT id FROM venues WHERE shop_id=$1 AND name=$2",
            [r.shop_id, r.name],
          );
          let venueId;
          if (existing.rows.length) {
            venueId = existing.rows[0].id;
          } else {
            const inserted = await client.query(
              "INSERT INTO venues(shop_id,name,address,capacity,floor_plan,created_at) VALUES($1,$2,$3,$4,'',$5) RETURNING id",
              [
                r.shop_id,
                r.name,
                typeof meta.address === "string" ? meta.address : "",
                seatRows * seatCols,
                new Date().toISOString(),
              ],
            );
            venueId = inserted.rows[0].id;
          }
          await client.query(
            "UPDATE resources SET venue_id=$1 WHERE id=$2",
            [venueId, r.id],
          );
        }
      }
      // R4-1 ticket backfill (2026-11-14): paid / completed /
      // disputed / refund_requested orders with zero tickets get
      // `quantity` tickets (seat_id NULL — seeded orders are
      // old-flow, with no sold seats); cancelled / refunded orders
      // get none. Guard: only orders with no tickets at all are
      // touched, so a re-run never duplicates. Runs on every setup;
      // only ticket-less orders are touched.
      {
        const rows = await client.query(
          "SELECT id, quantity FROM orders WHERE status IN ('paid','completed','disputed','refund_requested') AND NOT EXISTS (SELECT 1 FROM tickets WHERE tickets.order_id=orders.id) ORDER BY id ASC",
        );
        const qget = async (sql, ...params) =>
          (await client.query(postgresSql(sql), params)).rows[0];
        const qrun = async (sql, ...params) =>
          client.query(postgresSql(sql), params);
        for (const ord of rows.rows)
          await issueTicketsForOrder(qget, qrun, ord, () =>
            new Date().toISOString(),
          );
      }
      // R5-5 finance_ledger backfill (2026-11-14): existing money
      // movements get their ledger rows once, never twice. Paid /
      // completed orders get order_income (+amount); refunded orders
      // get refund_out (-amount — a full refund closes the counters,
      // so refunded_cents == amount); stored-value topup/bonus rows
      // get topup_in (+amount, note `svl:{id}` so a re-run can tell
      // them apart — order_id is NULL for top-ups, so (order_id,
      // kind) cannot dedupe them). Disputed / refund_requested
      // orders get nothing here: their pay already wrote
      // order_income live, and their refund_out comes with the
      // approval. Runs on every setup; only rows with no ledger
      // row yet are touched.
      await client.query(
        `INSERT INTO finance_ledger(shop_id,kind,amount_cents,order_id,note,created_at)
         SELECT r.shop_id,'order_income',o.amount,o.id,'',o.created_at
         FROM orders o JOIN resources r ON r.id=o.resource_id
         WHERE o.status IN ('paid','completed')
         AND NOT EXISTS (SELECT 1 FROM finance_ledger f WHERE f.order_id=o.id AND f.kind='order_income')`,
      );
      await client.query(
        `INSERT INTO finance_ledger(shop_id,kind,amount_cents,order_id,note,created_at)
         SELECT r.shop_id,'refund_out',-o.amount,o.id,'',o.created_at
         FROM orders o JOIN resources r ON r.id=o.resource_id
         WHERE o.status='refunded'
         AND NOT EXISTS (SELECT 1 FROM finance_ledger f WHERE f.order_id=o.id AND f.kind='refund_out')`,
      );
      await client.query(
        `INSERT INTO finance_ledger(shop_id,kind,amount_cents,order_id,note,created_at)
         SELECT a.shop_id,'topup_in',l.amount_cents,NULL,'svl:'||l.id,l.created_at
         FROM stored_value_ledger l JOIN stored_value_accounts a ON a.id=l.account_id
         WHERE l.kind IN ('topup','bonus')
         AND NOT EXISTS (SELECT 1 FROM finance_ledger f WHERE f.kind='topup_in' AND f.note='svl:'||l.id)`,
      );
      // Wave 3 #9: backfill the tagRules settings key for databases that
      // were seeded before it existed (incl. live Neon). Guard-key
      // INSERT, same idempotent pattern as enrichCatalog above: existing
      // rules are never overwritten, so an admin's edits survive reboots.
      await client.query(
        "INSERT INTO settings(key,value) VALUES('tagRules',$1) ON CONFLICT (key) DO NOTHING",
        [JSON.stringify(defaultTagRules)],
      );
      // R5-2: backfill the memberInsightRules settings key the same
      // way — existing rules are never overwritten, so an admin's
      // edits survive reboots.
      await client.query(
        "INSERT INTO settings(key,value) VALUES('memberInsightRules',$1) ON CONFLICT (key) DO NOTHING",
        [JSON.stringify(DEFAULT_MEMBER_INSIGHT_RULES)],
      );
      await client.query("COMMIT");
    } catch (error) {
      await client.query("ROLLBACK");
      throw error;
    } finally {
      client.release();
    }
  } catch (error) {
    await pool.end();
    throw error;
  }

  return {
    dialect: "postgres",
    prepare(sql) {
      return {
        all: async (...params) => (await execute(sql, params)).rows,
        get: async (...params) => (await execute(sql, params)).rows[0],
        run: async (...params) => {
          const insert =
            // R2-1: shows + performances join the tables whose INSERTs
            // get `RETURNING id` so run() can report lastInsertRowid.
            // R2-2: ticket_types joins them (tier create needs the id).
            // R2-3: pickup_points + ticket_templates join them too.
            // R2-4: venues + seat_templates join them too.
            // R2-5: seats joins them too (generate needs the ids).
            // R3-1: member_tiers joins them too (tier create needs the id).
            // R3-2: coupons joins them too (coupon create needs the id).
            // R3-3: flash_sales joins them too (sale create needs the id).
            // R3-4: coupon_rules + coupon_gifts join them too (rule /
            // gift create needs the id).
            // R3-5: sms_tasks joins them too (task create needs the id).
            // R3-6: stored_value_accounts + stored_value_ledger +
            // stored_value_plans join them too (top-up / grant /
            // plan create needs the id).
            // R4-1: tickets + verify_logs join them too (the
            // R3-5 lesson: an INSERT whose table is missing here
            // leaves lastInsertRowid empty, and any caller reading
            // the id back then hits 22P02 -> 500).
            // R4-2: print_logs joins them too (the print insert
            // needs its id the same way).
            // R5-1: event_aggregates joins them too (the aggregate
            // insert needs its id the same way).
            // R5-4: analysis_snapshots joins them too (the refresh
            // upsert needs its id the same way).
            // R5-5: alert_rules + finance_ledger join them too (the
            // rule create + every ledger write needs its id the
            // same way — the R3-5 lesson).
            // R6-1: licenses joins them too (the licence create
            // needs its id the same way — the R3-5 lesson).
            /^\s*INSERT\s+INTO\s+(users|resources|orders|demands|comments|messages|events|audit_logs|shops|shows|performances|ticket_types|pickup_points|ticket_templates|venues|seat_templates|seats|member_tiers|coupons|flash_sales|coupon_rules|coupon_gifts|sms_tasks|stored_value_accounts|stored_value_ledger|stored_value_plans|tickets|verify_logs|print_logs|event_aggregates|analysis_snapshots|alert_rules|finance_ledger|licenses)\b/i.test(
              sql,
            );
          const result = await execute(
            insert ? `${sql} RETURNING id` : sql,
            params,
          );
          return {
            changes: result.rowCount,
            lastInsertRowid: result.rows[0]?.id,
          };
        },
      };
    },
    close: () => pool.end(),
    async request(fn, { write, success, lock = true }) {
      const client = await pool.connect();
      try {
        await client.query(
          write ? "BEGIN" : "BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY",
        );
        if (write && lock) {
          // Small shared demo: serialize writes across all Vercel instances.
          // The lock is held before reading order state or checking availability.
          // lock:false is for nested transactions (login limiter): the outer
          // request already holds this lock, and taking it again on a
          // second connection would deadlock.
          await client.query("SELECT pg_advisory_xact_lock($1)", [writeLock]);
        }
        const result = await context.run(client, fn);
        await client.query(success() ? "COMMIT" : "ROLLBACK");
        return result;
      } catch (error) {
        await client.query("ROLLBACK");
        throw error;
      } finally {
        client.release();
      }
    },
  };
}
